<div class="modal fade" id="modalEquipamento" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title" id="tituloModalEquipamento">Novo equipamento</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" id="equipamento_id"><div class="row g-3"><div class="col-md-8"><label class="form-label">Descrição *</label><input class="form-control" name="descricao" id="equipamento_descricao" required></div><div class="col-md-4"><label class="form-label">Ativo</label><select class="form-select" name="ativo" id="equipamento_ativo"><option value="1">Sim</option><option value="0">Não</option></select></div><div class="col-md-6"><label class="form-label">Tipo</label><input class="form-control" name="tipo" id="equipamento_tipo"></div><div class="col-md-6"><label class="form-label">Capacidade</label><input type="number" class="form-control" name="capacidade" id="equipamento_capacidade" min="0" value="0"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form></div></div></div>